using System;using System.IO;using System.Collections.Generic;using System.Security.Cryptography;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps.EditorTools;
public static class SackMouthMemoryChecks {
 [Serializable]class Row{public string id;public bool sameRenderReference,collisionDataExact,sameCollisionReference;public long beforeRenderBytes,afterRenderBytes;}
 [Serializable]class Report{public bool pass;public string error;public long beforeUniqueMeshBytes,afterUniqueMeshBytes;public int beforeUniqueMeshes,afterUniqueMeshes,beforeMaterials,afterMaterials;public List<Row> rows=new List<Row>();}
 static string Arg(string key){var a=Environment.GetCommandLineArgs();return a[Array.IndexOf(a,key)+1];}
 static string Hash(Mesh m,bool physics=false){if(!m)return "none";using(var stream=new MemoryStream()){using(var w=new BinaryWriter(stream)){foreach(var v in m.vertices){w.Write(v.x);w.Write(v.y);w.Write(v.z);}if(!physics){foreach(var v in m.normals){w.Write(v.x);w.Write(v.y);w.Write(v.z);}foreach(var v in m.colors){w.Write(v.r);w.Write(v.g);w.Write(v.b);w.Write(v.a);}foreach(var v in m.uv){w.Write(v.x);w.Write(v.y);}}foreach(var v in m.triangles)w.Write(v);w.Flush();return Convert.ToBase64String(SHA256.Create().ComputeHash(stream.ToArray()));}}}
 static HashSet<Mesh> Meshes(Dictionary<string,GameObject> prefabs){var set=new HashSet<Mesh>();foreach(var p in prefabs.Values){foreach(var f in p.GetComponentsInChildren<MeshFilter>())if(f.sharedMesh)set.Add(f.sharedMesh);foreach(var c in p.GetComponentsInChildren<MeshCollider>())if(c.sharedMesh)set.Add(c.sharedMesh);}return set;}
 static int Materials(Dictionary<string,GameObject> prefabs){var set=new HashSet<Material>();foreach(var p in prefabs.Values)foreach(var r in p.GetComponentsInChildren<Renderer>())set.Add(r.sharedMaterial);return set.Count;}
 public static void Run(){var output=Arg("-memory-output");Directory.CreateDirectory(output);var report=new Report();int code=0;try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var rd=ScriptableObject.CreateInstance<UniversalRendererData>();var pipeline=UniversalRenderPipelineAsset.Create(rd);GraphicsSettings.defaultRenderPipeline=pipeline;QualitySettings.renderPipeline=pipeline;var priorFolder=AssetDatabase.GenerateUniqueAssetPath("Assets/ChestSurfaceBeforeMemory");AssetDatabase.CreateFolder("Assets",Path.GetFileName(priorFolder));var priorRoot=new GameObject("Before memory source");var prior=new Dictionary<string,GameObject>();SmallPropsV1.Build(Arg("-memory-before"),priorFolder,priorRoot.transform,Shader.Find("MapSharedProps/Lit"),prior);var next=MapSharedPropsBuilder.Build(Arg("-memory-after"));priorRoot.SetActive(false);next.root.SetActive(false);if(prior.Count!=43||next.prefabs.Count<43)throw new Exception("43 Native assets required");var current=new Dictionary<string,GameObject>();foreach(var id in prior.Keys)current.Add(id,next.prefabs[id]);var changed=new HashSet<string>(new[]{"tiedsack"});
  var camera=new GameObject("Paired mesh memory camera").AddComponent<Camera>();camera.gameObject.AddComponent<UniversalAdditionalCameraData>();camera.farClipPlane=1000;camera.targetTexture=new RenderTexture(1000,800,24);foreach(var set in new[]{prior,current}){var warm=new GameObject("Paired43Warmup");int k=0;foreach(var p in set.Values){var o=(GameObject)PrefabUtility.InstantiatePrefab(p,warm.transform);o.transform.position=new Vector3((k%8)*6,0,(k/8)*6);k++;}var renderers=warm.GetComponentsInChildren<Renderer>();var b=renderers[0].bounds;foreach(var r in renderers)b.Encapsulate(r.bounds);camera.transform.position=b.center+Vector3.up*(Mathf.Max(b.size.x,b.size.z)*2+b.size.y);camera.transform.rotation=Quaternion.LookRotation(Vector3.down,Vector3.forward);camera.Render();camera.Render();UnityEngine.Object.DestroyImmediate(warm);}
  foreach(var id in prior.Keys){var a=prior[id].GetComponent<MeshFilter>().sharedMesh;var b=current[id].GetComponent<MeshFilter>().sharedMesh;string ah=Hash(a),bh=Hash(b);var ac=prior[id].GetComponent<MeshCollider>();var bc=current[id].GetComponent<MeshCollider>();Mesh am=ac?ac.sharedMesh:null,bm=bc?bc.sharedMesh:null;var row=new Row{id=id,sameRenderReference=a==b,collisionDataExact=Hash(am,true)==Hash(bm,true),sameCollisionReference=am==bm,beforeRenderBytes=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(a),afterRenderBytes=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(b)};if(!changed.Contains(id)&&(!row.sameRenderReference||ah!=bh||row.beforeRenderBytes!=row.afterRenderBytes))throw new Exception("Unchanged root cache/data: "+id);if(!row.collisionDataExact)throw new Exception("Collision data changed: "+id);report.rows.Add(row);}
  var before=Meshes(prior);var after=Meshes(current);foreach(var m in before){Hash(m);report.beforeUniqueMeshBytes+=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(m);}foreach(var m in after){Hash(m);report.afterUniqueMeshBytes+=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(m);}report.beforeUniqueMeshes=before.Count;report.afterUniqueMeshes=after.Count;report.beforeMaterials=Materials(prior);report.afterMaterials=Materials(current);report.pass=true;AssetDatabase.SaveAssets();
 }catch(Exception e){code=1;report.error=e.ToString();Debug.LogException(e);}finally{File.WriteAllText(Path.Combine(output,"report.json"),JsonUtility.ToJson(report,true));EditorApplication.Exit(code);}}
}
